package com.hms.reminders;
import com.hms.appointments.*; import com.hms.tenancy.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/reminders") public class ReminderController {private final TenantRepository tenants;private final AppointmentRepository appointments;private final AppointmentReminderRepository reminders;public ReminderController(TenantRepository t,AppointmentRepository a,AppointmentReminderRepository r){tenants=t;appointments=a;reminders=r;} @GetMapping public List<AppointmentReminder> list(@PathVariable String tenantSlug){return reminders.findAllByTenantIdOrderByRemindAtAsc(tenant(tenantSlug));} @PostMapping("/appointments/{appointmentId}") @ResponseStatus(HttpStatus.CREATED) public AppointmentReminder create(@PathVariable String tenantSlug,@PathVariable UUID appointmentId,@Valid @RequestBody CreateReminderRequest r){UUID tenant=tenant(tenantSlug);Appointment a=appointments.findById(appointmentId).filter(x->x.getTenantId().equals(tenant)).orElseThrow(()->new IllegalArgumentException("Appointment not found"));if(!r.remindAt().isBefore(a.getStartsAt()))throw new IllegalArgumentException("Reminder must be before appointment");return reminders.save(new AppointmentReminder(tenant,a.getId(),r));} private UUID tenant(String slug){return tenants.findBySlug(slug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(slug));}}
